local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local ResourceModule = CS.Engine.Modules.ResourceModule
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
local GameObject = CS.UnityEngine.GameObject
local KTool = CS.Engine.Lib.KTool

---@class ScreenAttackEffect : BaseEffect
local ScreenAttackEffect = Class("ScreenAttackEffect", BaseEffect)

local NewChapterConstants = import('Game.Chapter.NewChapterConstants')

local second = 5

function ScreenAttackEffect:__init()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
end

function ScreenAttackEffect:__delete()
    self._isFinish = nil
    self._loadedRes = nil
    self._co = nil
end

---@param parameters NewChapter2DVo
function ScreenAttackEffect:Initialize(parameters)
    base.Initialize(self, parameters)
    self._isFinish = false
    
end

function ScreenAttackEffect:StartEffect(object)
    base.StartEffect(self, object)
    self._co = cs_coroutine.start(function()
        self._loadedRes = {}
        local loader = ResourceModule.LoadBundleAsync(NewChapterConstants.AttackEffectPath, nil, true)
        while not loader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end
        if not KTool.IsActiveInHierarchy(object.gameObject) then
            KTool.SetActive(object.gameObject, true)
            KTool.SetActive(object.transform.parent, true)
        end
        if not isNull(loader.ResultObject) then
            -- local modelIns = GameObject.Instantiate(loader.ResultObject)
            local modelIns = loader:Instantiate()
            loader:Release()
            modelIns.transform:SetParent(object.transform)
            modelIns.transform.localPosition = Vector3.New(0,0,0)
            modelIns.transform.localScale = Vector3.New(1,1,1)
            self._loadedRes.go = modelIns
            
            KTool.SetActive(modelIns.gameObject, true)

            coroutine.yield(Yielders.GetWaitForSeconds(second))

            KTool.SetActive(modelIns.gameObject, false)

            self._isFinish = true
            
        else
            loader:Release()
            self._loadedRes = nil
        end

        
    end)
end

function ScreenAttackEffect:IsFinish()
    base.IsFinish(self)
    return self._isFinish
end

function ScreenAttackEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function ScreenAttackEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    if self._co ~= nil then
        cs_coroutine.stop(self._co)
    end
    
    if self._loadedRes ~= nil then
        GameObject.Destroy(self._loadedRes.go)
        -- self._loadedRes:Release()
    end

    if KTool.IsActiveInHierarchy(object.gameObject) then
        KTool.SetActive(object.gameObject, false)
        KTool.SetActive(object.transform.parent, false)
    end
    
end

return ScreenAttackEffect